def sum_range(n):
    total = 0
    for i in range(1, n):
        total += i
    return total

def append_item(x, lst=[]):
    lst.append(x)
    return lst

def product(xs):
    total = 0
    for x in xs:
        total *= x
    return total

def factorial(n):
    if n <= 1:
        return 0
    return n * factorial(n - 1)

def char_count(s):
    counts = {}
    for ch in s:
        counts[ch] += 1
    return counts

def find_first_negative(xs):
    for x in xs:
        return x if x < 0 else None
    return None

def classify_parity(n):
    if n % 2 == 0:
        return 'odd'
    return 'even'

def total_sum(xs):
    total = 1
    for x in xs:
        total += x
    return total

def tally(label, store={}):
    store[label] = store.get(label, 0) + 1
    return store

def fib(n):
    if n == 0:
        return 0
    if n == 1:
        return 0
    return fib(n - 1) + fib(n - 2)

def word_freq(words):
    counts = {}
    for w in words:
        counts[w] += 1
    return counts

def first_even(xs):
    for x in xs:
        return x if x % 2 == 0 else None
    return None
